const item = $input.first();
const j = item.json;
const isCallback = !!j.callback_query;

const chatId = isCallback ? j.callback_query.message.chat.id : (j.message ? j.message.chat.id : null);
const messageId = isCallback ? j.callback_query.message.message_id : null;
const callbackData = isCallback ? j.callback_query.data : null;
const rawText = isCallback ? callbackData : (j.message && j.message.text ? j.message.text.trim() : "");
const document = (!isCallback && j.message && j.message.document) ? j.message.document : null;

return [{
  json: {
    chatId, messageId, isCallback,
    text: (rawText || "").toLowerCase(),
    rawText: rawText || "",
    isDocument: !!document,
    fileId: document ? document.file_id : null,
    fileName: document ? (document.file_name || ("dataset_" + Date.now() + ".csv")) : null,
    original: j
  }
}];

const item = $input.first();

let session = {
    state: "idle",
    dataset_path: null,
    dataset_name: null,
    pending_files: [],
    columns: [],
    target_column: null,
    problem_type: null,
    available_models: [],
    selected_models: []
};

try {

    if (
        item.json.data &&
        Array.isArray(item.json.data) &&
        item.json.data.length > 0
    ) {
        session = {
            ...session,
            ...item.json.data[0]
        };
    }

}
catch(e){
    console.log(e);
}

return [
{
    json: session
}
];

const d = $input.first().json;
const text = (d.text || "").trim();
const state = d.state || "idle";
let route = "fallback";


if (text === "back") {

  switch (state) {

    case "idle":
      route = "show_menu";
      break;

    case "upload_ds":
      route = "prompt_upload";
      break;

    case "waiting_for_previous_selection":
      route = "list_previous";
      break;

    case "dataset_menu":
      route = d.dataset_name ? "select_previous" : "handle_upload";
      break;

    case "guess_plan":
      route = "select_previous";
      break;

    case "waiting_target_column":
      route = "train_recommended";
      break;

    case "waiting_problem_type":
      route = "customize_start";
      break;

    case "waiting_models": 
      route = "pick_target";
      break;

    case "HP_train":
      route = "train_recommended";
      break;

    case "HP_user_wait":
        route = "models_done";
        break;

    case "confirm_train":
        route = "HP_train";
        break;

    case "training":
        route = "confirm_train";
        break;

    case "confirm_train":
      route = "toggle_model";
      break;

    // case "training":
    //   route = "models_done";
    //   break;

    default:
      route = "show_menu";
  }

}
else if (d.isDocument && state === "waiting_for_csv")
    route = "handle_upload";

else if (d.isDocument)
    route = "unexpected_file";

else if (
    text === "start" ||
    text === "/start" ||
    text === "main menu" ||
    text === "new"
)
    route = "show_menu";

else if (
    text === "upload" &&
    (
        state === "idle" ||
        state === "waiting_for_previous_selection" ||
        state === "waiting_for_csv"
    )
)
    route = "prompt_upload";

else if (
    text === "previous" &&
    (
        state === "idle" ||
        state === "waiting_for_previous_selection" ||
        state === "waiting_for_csv"
    )
)
    route = "list_previous";

else if (
    text !== "" &&
    text !== "upload" &&
    text !== "previous" &&
    text !== "help" &&
    state === "waiting_for_previous_selection"
)
    route = "select_previous";

else if (
    state === "dataset_menu" &&
    (text === "train" || text.startsWith("train"))
)
    route = d.dataset_path ? "train_recommended" : "no_dataset";

else if (
    text === "customize" &&
    state === "guess_plan"
)
    route = d.dataset_path ? "customize_start" : "no_dataset";

else if (
    text.startsWith("targetidx:") &&
    state === "waiting_target_column"
)
    route = "pick_target";

else if (
    text.startsWith("ptype:") &&
    state === "waiting_problem_type"
)
    route = "pick_problem_type";

else if (
    text.startsWith("togglemodelidx:") &&
    state === "waiting_models"
)
    route = "toggle_model";

else if (
    text === "models done" &&
    state === "waiting_models"
)
    route = "models_done";

else if (
    text === "hp train" &&
    state === "HP_train"
)
    route = "HP_train";

else if (
    text === "no" &&
    state === "HP_train"
)
    route = "HP_ai";

else if (
    state === "HP_user_wait" &&
    text !== "" &&
    text.toLowerCase() !== "back"
)
    route = "HP_ai";

else if (
    text === "confirm train" &&
    state === "confirm_train"
)
    route = "confirm_yes";

// else if (
//     (text === "confirm train" &&
//     state === "confirm_train")||(text === "No" && state === "HP_user_wait")
// )
//     route = "confirm_yes";

else if (
    text === "help" ||
    text === "/help"
)
    route = "show_help";

return [{
    json: {
        ...d,
        route
    }
}];

const items = $input.all();
const files = items
  .map(it => (it.binary && it.binary.data && it.binary.data.fileName) ? it.binary.data.fileName : null)
  .filter(Boolean);
return [{ json: { chatId: $('Determine Route').item.json.chatId, files, hasFiles: files.length > 0 } }];

const files = $json.files || [];

const list = files.length
  ? files.map((f, i) => `${i + 1}. ${f}`).join("\n")
  : "No datasets found.";

return [{
  json: {
    chatId: $json.chatId,
    text:
`📁 Available datasets:

${list}

Reply with the dataset name exactly as shown.`
  }
}];

return [{
  json: {
    chatId: $json.chatId,

    state: "waiting_for_previous_selection",

    dataset_path: null,
    dataset_name: null,

    pending_files: $('Has Files?').first().json.files,

    columns: [],
    target_column: null,
    problem_type: null,
    available_models: [],
    selected_models: []
  }
}];

const d = $input.first().json;

const typed = String(d.rawText || d.text || "").trim().toLowerCase();

const files = d.pending_files || [];

const fileName = files.find(
    f => f.toLowerCase() === typed
);

if (!fileName) {
    return [{
        json: {
            chatId: d.chatId,
            ok: false
        }
    }];
}

return [{
    json: {
        chatId: d.chatId,
        ok: true,
        dataset_name: fileName,
        dataset_path: `/shared/uploads/${fileName}`
    }
}];

const d = $('Parse Selection').item.json;

return [
{
  json: {
    chatId: d.chatId,

    state: d.ok ? "dataset_menu" : "waiting_for_previous_selection",

    dataset_path: d.ok
      ? `/shared/uploads/${d.dataset_name}`
      : null,

    dataset_name: d.ok
      ? d.dataset_name
      : null,

    pending_files: [],

    columns: [],
    target_column: null,
    problem_type: null,
    available_models: [],
    selected_models: []
  }
}
];

const r = $('Determine Route').item.json;
const file = $('Determine Route').item.json.fileName;

return [{
  json: {
    chatId: r.chatId,
    state: "dataset_menu",

    dataset_path: "/shared/uploads/" + file,
    dataset_name: file,

    pending_files: [],
    columns: [],
    target_column: null,
    problem_type: null,
    available_models: [],
    selected_models: []
  }
}];

const rows = $input.all().map(i => i.json);

if (!rows.length) {
  throw new Error("Dataset is empty.");
}

const columns = Object.keys(rows[0]);

// -------- Guess target column --------

const preferredTargets = [
  "converted",
  "target",
  "label",
  "class",
  "output",
  "result",
  "prediction",
  "y"
];

let target_column =
columns.find(c =>
    preferredTargets.includes(c.toLowerCase())
);

if (!target_column) {
    target_column = columns[columns.length - 1];
}

// -------- Guess problem type --------

const values = new Set();

for (const row of rows) {
    values.add(String(row[target_column]));
}

const uniqueCount = values.size;

const problem_type =
(uniqueCount <= 20)
?
"classification"
:
"regression";

// -------- Recommended models --------

const CLASS = [
"Random Forest",
"Gradient Boosting",
"Logistic Regression"
];

const REG = [
"Random Forest Regressor",
"Gradient Boosting Regressor",
"Linear Regression"
];

const selected_models =
problem_type === "classification"
?
CLASS
:
REG;

return [{
json:{
chatId:$("Determine Route").first().json.chatId,

columns,

target_column,

problem_type,

selected_models,

dataset_path:$("Determine Route").first().json.dataset_path,

dataset_name:$("Determine Route").first().json.dataset_name
}
}];

const d = $("Guess Plan").first().json;

return [{
    json: {
        chatId: d.chatId,

        state: "guess_plan",

        dataset_path: d.dataset_path,
        dataset_name: d.dataset_name,
        columns: d.columns,
        target_column: d.target_column,
        problem_type: d.problem_type,
        available_models: d.available_models || [],
        selected_models: d.selected_models,
        pending_files: []
    }
}];

const rows = $input.all().map(i => i.json);

if (!rows.length) {
    throw new Error("Dataset is empty.");
}

const columns = Object.keys(rows[0]);

const text =
`🎯 Choose the target column

${columns.map((c, i) => `${i + 1}. ${c}`).join("\n")}

`;

return [{
    json: {
        chatId: $("Determine Route").first().json.chatId,
        columns,
        text
    }
}];

const d = $("Build Column Buttons").first().json;

return [{
    json: {
        chatId: d.chatId,

        state: "waiting_target_column",

        dataset_path: $("Determine Route").first().json.dataset_path,

        dataset_name: $("Determine Route").first().json.dataset_name,

        columns: d.columns,

        target_column: null,

        problem_type: null,

        available_models: [],

        selected_models: [],

        pending_files: []
    }
}];

const d = $input.first().json;

const text = String(d.text || "").trim();

if (!text.startsWith("targetidx:")) {
    return [{
        json: d
    }];
}

const idx = parseInt(
    text.split(":")[1],
    10
);

if (
    Number.isNaN(idx) ||
    idx < 1 ||
    idx > (d.columns || []).length
) {
    return [{
        json: {
            ...d,
            error: "Invalid target index."
        }
    }];
}

return [{
    json: {
        ...d,
        target_column: d.columns[idx - 1]
    }
}];

const d = $input.first().json;

const problem_type = String(d.text)
    .split(":")[1]
    .trim()
    .toLowerCase();

const CLASS = [
    "Random Forest",
    "Gradient Boosting",
    "Logistic Regression",
    "Decision Tree",
    "AdaBoost",
    "Naive Bayes",
    "Support Vector Machine",
    "KNN",
    "Neural Network"
];

const REG = [
    "Random Forest Regressor",
    "Gradient Boosting Regressor",
    "Linear Regression",
    "Ridge Regression",
    "Lasso Regression",
    "Decision Tree Regressor",
    "Support Vector Regressor",
    "KNN Regressor"
];

const available_models =
    problem_type === "classification"
        ? CLASS
        : REG;

return [{
    json: {
        ...d,
        problem_type,
        available_models,
        selected_models: []
    }
}];

const d = $input.first().json;
const avail = d.available_models || [];
const sel = d.selected_models || [];
const rows = avail.map((m, i) => ({
  row: { buttons: [{ text: (sel.includes(m) ? "\u2705 " : "\u2b1c ") + m, additionalFields: { callback_data: "toggle_model_idx:" + i } }] }
}));
rows.push({ row: { buttons: [{ text: "\u2714\ufe0f Done", additionalFields: { callback_data: "models_done" } }] } });
return [{ json: { ...d, rows } }];

const d = $input.first().json;

const text = String(d.text || "").trim();

const idx = Number(text.replace("togglemodelidx:", ""));

const available = d.available_models || [];

if (
    Number.isNaN(idx) ||
    idx < 0 ||
    idx >= available.length
) {
    return [{
        json: {
            ...d,
            error: "Invalid model selection."
        }
    }];
}

const model = available[idx];

let selected = [...(d.selected_models || [])];

if (selected.includes(model)) {
    selected = selected.filter(m => m !== model);
} else {
    selected.push(model);
}

return [{
    json: {
        ...d,
        selected_models: selected
    }
}];

const d = $input.first().json;

const available = d.available_models || [];
const selected = d.selected_models || [];

const modelList = available
    .map((m, i) => {
        const mark = selected.includes(m) ? "✅" : "⬜";
        return `${mark} ${i}. ${m}`;
    })
    .join("\n");

return [{
    json: {
        ...d,
        modelList
    }
}];

const d = $input.first().json;
const selected = (d.selected_models && d.selected_models.length) ? d.selected_models : (d.available_models || []).slice(0, 3);
return [{ json: { ...d, selected_models: selected } }];

const s = $("Determine Route").first().json;


const recommended_models =
    s.recommended_models ??
    (s.selected_models || []).map((name,index)=>({
        priority:index+1,
        name,
        params:{}
    }));

const payload = {

    chatId: s.chatId,

    dataset_path: s.dataset_path,
    dataset_name: s.dataset_name,

    problem_type: s.problem_type,
    target_column: s.target_column,

    recommended_models: recommended_models,

    test_size: 0.2,
    random_state: 42,

    confidence: 1.0,

    visualizations: [
        "confusion_matrix",
        "feature_importance",
        "roc_curve"
    ]
};

return [{
    json: {
        chatInput: JSON.stringify(payload)
    }
}];

// Combine the engine's editable-param schema with the user's request.
// Only the schema for the currently-selected models is sent to the LLM,
// which keeps the prompt (and token cost) small.

const trigger = $('When Executed by Another Workflow').first().json;
const schemaResp = $input.first().json;

const fullSchema = schemaResp.schema || {};
const selected = Array.isArray(trigger.selected_models)
  ? trigger.selected_models
  : [];
const userMessage = (trigger.user_message || '').toString().trim();

// Slim schema -> only selected models, only what the LLM needs.
const slim = {};
for (const name of selected) {
  const spec = fullSchema[name];
  if (!spec) continue;
  const params = {};
  for (const [p, meta] of Object.entries(spec.params || {})) {
    params[p] = {
      type: meta.type,
      default: meta.default,
      ...(meta.min !== undefined ? { min: meta.min } : {}),
      ...(meta.max !== undefined ? { max: meta.max } : {}),
      ...(meta.choices !== undefined ? { choices: meta.choices } : {}),
      ...(meta.nullable ? { nullable: true } : {})
    };
  }
  slim[name] = params;
}

const userPrompt =
  'Selected models and their editable hyperparameters (with valid ranges):\n' +
  JSON.stringify(slim, null, 2) +
  '\n\nUser request: "' + userMessage + '"\n\n' +
  'Return the JSON patch now.';

return [{
  json: {
    chatId: trigger.chatId,
    problem_type: trigger.problem_type,
    target_column: trigger.target_column,
    dataset_path: trigger.dataset_path,
    dataset_name: trigger.dataset_name,
    selected_models: selected,
    slim_schema: slim,
    user_message: userMessage,
    user_prompt: userPrompt
  }
}];

