const d = $input.first().json;

const selected = d.selected_models || [];

const MODEL_SCHEMA = {

    "Random Forest": {
        n_estimators: {
            type: "int",
            min: 10,
            max: 1000,
            default: 100
        },
        max_depth: {
            type: "int",
            min: 1,
            max: 100,
            default: null
        },
        min_samples_split: {
            type: "int",
            min: 2,
            max: 20,
            default: 2
        },
        min_samples_leaf: {
            type: "int",
            min: 1,
            max: 20,
            default: 1
        },
        criterion: {
            type: "choice",
            choices: ["gini", "entropy", "log_loss"],
            default: "gini"
        }
    },

    "Gradient Boosting": {
        n_estimators: {
            type: "int",
            min: 10,
            max: 1000,
            default: 100
        },
        learning_rate: {
            type: "float",
            min: 0.001,
            max: 1,
            default: 0.1
        },
        max_depth: {
            type: "int",
            min: 1,
            max: 20,
            default: 3
        },
        subsample: {
            type: "float",
            min: 0.1,
            max: 1.0,
            default: 1.0
        }
    },

    "Logistic Regression": {
        C: {
            type: "float",
            min: 0.0001,
            max: 1000,
            default: 1.0
        },
        penalty: {
            type: "choice",
            choices: ["l1", "l2", "elasticnet", null],
            default: "l2"
        },
        solver: {
            type: "choice",
            choices: [
                "lbfgs",
                "liblinear",
                "newton-cg",
                "sag",
                "saga"
            ],
            default: "lbfgs"
        },
        max_iter: {
            type: "int",
            min: 50,
            max: 5000,
            default: 100
        }
    },

    "Decision Tree": {
        max_depth: {
            type: "int",
            min: 1,
            max: 100,
            default: null
        },
        min_samples_split: {
            type: "int",
            min: 2,
            max: 20,
            default: 2
        },
        min_samples_leaf: {
            type: "int",
            min: 1,
            max: 20,
            default: 1
        },
        criterion: {
            type: "choice",
            choices: [
                "gini",
                "entropy",
                "log_loss"
            ],
            default: "gini"
        }
    },

    "AdaBoost": {
        n_estimators: {
            type: "int",
            min: 10,
            max: 1000,
            default: 50
        },
        learning_rate: {
            type: "float",
            min: 0.001,
            max: 5,
            default: 1.0
        }
    },

    "Naive Bayes": {
        var_smoothing: {
            type: "float",
            min: 1e-12,
            max: 1,
            default: 1e-9
        }
    },

    "Support Vector Machine": {
        C: {
            type: "float",
            min: 0.001,
            max: 1000,
            default: 1
        },
        kernel: {
            type: "choice",
            choices: [
                "linear",
                "poly",
                "rbf",
                "sigmoid"
            ],
            default: "rbf"
        },
        gamma: {
            type: "choice",
            choices: [
                "scale",
                "auto"
            ],
            default: "scale"
        }
    },

    "KNN": {
        n_neighbors: {
            type: "int",
            min: 1,
            max: 50,
            default: 5
        },
        weights: {
            type: "choice",
            choices: [
                "uniform",
                "distance"
            ],
            default: "uniform"
        },
        metric: {
            type: "choice",
            choices: [
                "minkowski",
                "euclidean",
                "manhattan"
            ],
            default: "minkowski"
        }
    },

    "Neural Network": {
        hidden_layer_sizes: {
            type: "tuple",
            default: "(100,)"
        },
        activation: {
            type: "choice",
            choices: [
                "relu",
                "tanh",
                "logistic"
            ],
            default: "relu"
        },
        alpha: {
            type: "float",
            min: 0.000001,
            max: 1,
            default: 0.0001
        },
        learning_rate_init: {
            type: "float",
            min: 0.00001,
            max: 1,
            default: 0.001
        },
        max_iter: {
            type: "int",
            min: 100,
            max: 5000,
            default: 200
        }
    }

};

const lines = [];

for (const model of selected) {

    const params = MODEL_SCHEMA[model];

    if (!params) continue;

    lines.push(`🔹 *${model}*`);

    for (const [param, meta] of Object.entries(params)) {

        let line = `• ${param}`;

        if (meta.type)
            line += ` (${meta.type})`;

        if (meta.choices)
            line += ` → ${meta.choices.join(", ")}`;

        else if (
            meta.min !== undefined &&
            meta.max !== undefined
        )
            line += ` → ${meta.min} to ${meta.max}`;

        if (meta.default !== undefined)
            line += ` (default: ${meta.default})`;

        lines.push(line);
    }

    lines.push("");
}

return [{
    json: {
        ...d,
        HP_train_values: lines.join("\n"),
        HP_schema: MODEL_SCHEMA
    }
}];

const original = $("Code in JavaScript").first().json;

let ai = {};

try {

    let txt = String($json.output).trim();

    // Remove markdown code fences if present
    txt = txt.replace(/^```json/i, "");
    txt = txt.replace(/^```/, "");
    txt = txt.replace(/```$/, "");

    // Remove surrounding backticks
    txt = txt.replace(/^`/, "");
    txt = txt.replace(/`$/, "");

    txt = txt.trim();

    ai = JSON.parse(txt);

} catch (e) {

    throw new Error(
        "Could not parse AI output:\n\n" + $json.output
    );

}

const DEFAULTS = {

    "Random Forest": {
        n_estimators: 100,
        max_depth: null,
        min_samples_split: 2,
        min_samples_leaf: 1,
        criterion: "gini"
    },

    "Gradient Boosting": {
        n_estimators: 100,
        learning_rate: 0.1,
        max_depth: 3,
        subsample: 1.0
    },

    "Logistic Regression": {
        C: 1,
        penalty: "l2",
        solver: "lbfgs",
        max_iter: 100
    },

    "Decision Tree": {
        max_depth: null,
        min_samples_split: 2,
        min_samples_leaf: 1,
        criterion: "gini"
    },

    "AdaBoost": {
        n_estimators: 50,
        learning_rate: 1
    },

    "Naive Bayes": {

    },

    "Support Vector Machine": {
        C: 1,
        kernel: "rbf",
        gamma: "scale"
    },

    "KNN": {
        n_neighbors: 5,
        weights: "uniform",
        metric: "minkowski"
    },

    "Neural Network": {
        hidden_layer_sizes: 100,
        activation: "relu",
        alpha: 0.0001,
        learning_rate_init: 0.001,
        max_iter: 200
    }

};

const recommended_models = [];

const editedModels = ai.recommended_models || {};

for (const [i, model] of original.selected_models.entries()) {

    const defaults = DEFAULTS[model] || {};

    const edited = editedModels[model] || {};

    recommended_models.push({

        priority: i + 1,

        name: model,

        params: {

            ...defaults,

            ...edited

        }

    });

}

return [{

    json: {

        ...original,

        HP_train_values:
            ai.updated_HP_train_values || original.HP_train_values,

        recommended_models

    }

}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

// Defensively parse the LLM output and merge it into recommended_models.
// The engine re-validates and clamps everything server-side, so this node
// only needs to produce well-formed structure and never crash on bad output.

const ctx = $('Build AI Prompt').first().json;
const selected = ctx.selected_models || [];
const slim = ctx.slim_schema || {};

let raw = $input.first().json;
let text = raw.output ?? raw.text ?? raw.response ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);

// Strip markdown fences / surrounding prose, keep the outermost JSON object.
function extractJson(s) {
  if (!s) return {};
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end === -1 || end < start) return {};
  try {
    return JSON.parse(s.slice(start, end + 1));
  } catch (e) {
    return {};
  }
}

const patch = extractJson(text);

// Build recommended_models: every selected model, with AI params where given.
// Keep only params that exist in that model's schema (belt-and-suspenders;
// the engine also drops unknowns).
const recommended_models = selected.map((name, index) => {
  const allowed = slim[name] || {};
  const proposed = (patch && typeof patch === 'object' && patch[name]) ? patch[name] : {};
  const params = {};
  for (const [k, v] of Object.entries(proposed)) {
    if (k in allowed) params[k] = v;
  }
  return { priority: index + 1, name, params };
});

// Human-readable summary of what changed, for a Telegram confirmation.
const changed = recommended_models.filter(m => Object.keys(m.params).length > 0);
let summary;
if (changed.length === 0) {
  summary = 'No hyperparameter changes were applied (using defaults).';
} else {
  summary = changed.map(m => {
    const kv = Object.entries(m.params).map(([k, v]) => `${k}=${v}`).join(', ');
    return `• ${m.name}: ${kv}`;
  }).join('\n');
}

return [{
  json: {
    chatId: ctx.chatId,
    problem_type: ctx.problem_type,
    target_column: ctx.target_column,
    dataset_path: ctx.dataset_path,
    dataset_name: ctx.dataset_name,
    selected_models: selected,
    recommended_models,
    customization_summary: summary,
    ai_raw: text
  }
}];
